void tsk_rs_pts_ctrl( Boolean state )
{
	if( tsk_rs_pts_callback )
	{
		if( tsk_rs_invalid_state() == TRUE )
		{
			tsk_rs_pts_callback( FALSE );
		}
		else
		{
			tsk_rs_pts_callback( state );
		}
	}
}

